"""Checks if the two behavior ID strings are the same (e.g. 'fd' vs. 'fd_r' should return
    True).

    Args:
        behavior_id_str_1: Behavior ID as a string.
        behavior_id_str_2: Behavior ID as a string.
    """
def is_same_behavior_id_str(behavior_id_str_1: Any, behavior_id_str_2: Any) -> object {
    return (
        behavior_id_str_1.startswith(behavior_id_str_2)
        or behavior_id_str_2.startswith(behavior_id_str_1)
    );
}
